generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel ?avgHoldingGainPct ?totalRebalanceAmount ?avgScenarioChangePct ?totalCashFlow
WHERE {
  {
    SELECT ?cat (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingGainPct)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasCategory ?cat ;
           wm:hasHolding ?hold .
      ?hold wm:returnsPct ?returnsPct .
    }
    GROUP BY ?cat
  }
  OPTIONAL {
    SELECT ?cat (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasCategory ?cat ;
           wm:hasRebalancingAction ?reb .
      ?reb wm:amount ?rebAmount .
    }
    GROUP BY ?cat
  }
  OPTIONAL {
    SELECT ?cat (AVG(xsd:decimal(?scenarioChange)) AS ?avgScenarioChangePct)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasCategory ?cat ;
           wm:hasScenarioRebalancing ?sc .
      ?sc wm:newAllocationPct ?newPct ;
          wm:currentAllocationPct ?curPct .
      BIND ((xsd:decimal(?newPct) - xsd:decimal(?curPct)) AS ?scenarioChange)
    }
    GROUP BY ?cat
  }
  OPTIONAL {
    SELECT ?cat (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasCategory ?cat ;
           wm:hasCashFlow ?cf .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?cat
  }
  ?cat rdfs:label ?categoryLabel .
}

